import{_ as a,o as i,c as t,a2 as l}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Сборка проекта","description":"","frontmatter":{"pageId":"developers/build","contentRevision":1},"headers":[],"relativePath":"ru/developers/build.md","filePath":"ru/developers/build.md"}'),o={name:"ru/developers/build.md"};function r(s,e,n,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="сборка-проекта" tabindex="-1">Сборка проекта <a class="header-anchor" href="#сборка-проекта" aria-label="Permalink to &quot;Сборка проекта&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Установи SDK из global.json; версии пакетов централизованы в Directory.Packages.props. Из корня выполни:</p><p><code>dotnet build Rimlink.sln</code></p><p><code>dotnet test Rimlink.sln -nologo -v q</code></p><p>Мод не включён в solution: закрой игру и используй PowerShell scripts/Build-ClientMod.ps1 -RimWorldDir &lt;game&gt; -InstallTo &lt;game/Mods&gt;. -BundleHarmony допустим лишь для локального запуска без отдельного Harmony, не релиза. scripts/Package-Release.ps1 собирает release ZIP.</p><p>Для wiki: npm --prefix wiki ci --ignore-scripts, затем run test:checks, check:content, check:reference, build, check:links. Node 24 закреплён отдельно. Для BridgeTools нужен отдельный Build-BridgeTools.ps1 и установленная игра.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Не заменяй DLL работающей игры и не перезапускай чужой экземпляр. Успешный solution build не доказывает сборку мода и игру. Не коммить bin/obj/data/сейвы/секреты и generated wiki output.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./testing">Тестирование и приёмка</a></li><li><a href="./contributing">Вклад и сопровождение wiki</a></li><li><a href="./../admins/hosting">Размещение и запуск</a></li></ul>',12)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
